package io.invenlio.warehouse;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.*;import org.springframework.boot.test.context.*;import org.springframework.boot.testcontainers.service.connection.*;import org.springframework.boot.webmvc.test.autoconfigure.*;import org.springframework.dao.*;import org.springframework.jdbc.core.*;import org.springframework.test.context.*;import org.springframework.test.web.servlet.*;import org.testcontainers.junit.jupiter.*;import org.testcontainers.postgresql.*;import static org.junit.jupiter.api.Assertions.*;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.jwt;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@Testcontainers @SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test") class WarehouseSecurityIntegrationTest{static final UUID A=UUID.fromString("11111111-1111-4111-8111-111111111111"),B=UUID.fromString("22222222-2222-4222-8222-222222222222"),WA=UUID.fromString("10000000-0000-4000-8000-000000000001"),WB=UUID.fromString("20000000-0000-4000-8000-000000000001"),ZA=UUID.fromString("10000000-0000-4000-8000-000000000002"),ZB=UUID.fromString("20000000-0000-4000-8000-000000000002"),LA=UUID.fromString("10000000-0000-4000-8000-000000000003"),LB=UUID.fromString("20000000-0000-4000-8000-000000000003");@Container @ServiceConnection static final PostgreSQLContainer DB=new PostgreSQLContainer("postgres:17.6-alpine");@Autowired JdbcTemplate db;@Autowired MockMvc mvc;
@BeforeEach void seed(){db.update("DELETE FROM warehouse_operational_locations");db.update("DELETE FROM warehouse_locations");db.update("DELETE FROM warehouse_zones");db.update("DELETE FROM warehouses");db.update("DELETE FROM audit_events");db.update("DELETE FROM membership_roles");db.update("DELETE FROM role_permissions");db.update("DELETE FROM organization_memberships");db.update("DELETE FROM roles");db.update("DELETE FROM user_identities");db.update("DELETE FROM organizations");org(A,"a");org(B,"b");var user=UUID.randomUUID();var member=UUID.randomUUID();var role=UUID.randomUUID();db.update("INSERT INTO user_identities(id,keycloak_subject,status,created_at,updated_at)VALUES (?,?,'ACTIVE',now(),now())",user,"user-a");db.update("INSERT INTO organization_memberships(id,tenant_id,user_identity_id,status,created_at,updated_at,version)VALUES (?,?,?,'ACTIVE',now(),now(),0)",member,A,user);db.update("INSERT INTO roles(id,tenant_id,name,system_role,created_at,updated_at,version)VALUES (?,?,?,false,now(),now(),0)",role,A,"WAREHOUSE_TEST");for(String p:List.of("warehouse:read","warehouse:create","warehouse:update","warehouse:archive","warehouse-location:read","warehouse-location:manage"))db.update("INSERT INTO role_permissions VALUES (?,?,?)",A,role,p);db.update("INSERT INTO membership_roles VALUES (?,?,?)",A,member,role);warehouse(A,WA,"A-01");warehouse(B,WB,"B-01");zone(A,WA,ZA,"A");zone(B,WB,ZB,"B");location(A,WA,ZA,LA,"A","SCAN-A");location(B,WB,ZB,LB,"B","SCAN-B");}
@Test void ownWarehouseReadableOtherTenantHidden()throws Exception{mvc.perform(get("/api/v1/warehouses/"+WA).with(token())).andExpect(status().isOk());mvc.perform(get("/api/v1/warehouses/"+WB).with(token())).andExpect(status().isNotFound());mvc.perform(get("/api/v1/warehouse-locations/"+LB).with(token())).andExpect(status().isNotFound());}
@Test void scanLookupNeverLeaksOtherTenant()throws Exception{mvc.perform(get("/api/v1/warehouse-locations/lookup?scanCode=SCAN-B").with(token())).andExpect(status().isNotFound());}
@Test void crossWarehouseParentRejected()throws Exception{var w2=UUID.randomUUID();var z2=UUID.randomUUID();var l2=UUID.randomUUID();warehouse(A,w2,"A-02");zone(A,w2,z2,"Z2");location(A,w2,z2,l2,"L2","SCAN-2");mvc.perform(post("/api/v1/warehouses/"+WA+"/locations").with(token()).contentType("application/json").content("{\"zoneId\":\""+ZA+"\",\"parentId\":\""+l2+"\",\"code\":\"X\",\"type\":\"BIN\",\"sequence\":0,\"scanCode\":\"SCAN-X\"}" )).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("CROSS_WAREHOUSE_LOCATION_REFERENCE"));}
@Test void staleWarehouseUpdateConflicts()throws Exception{mvc.perform(patch("/api/v1/warehouses/"+WA).with(token()).contentType("application/json").content("{\"code\":\"A-01\",\"name\":\"A\",\"timezone\":\"UTC\",\"version\":9}" )).andExpect(status().isConflict());}
@Test void warehouseLifecycleRoutesUseDomainStates()throws Exception{mvc.perform(post("/api/v1/warehouses/"+WA+"/activate").with(token()).contentType("application/json").content("{\"version\":0}")).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("ACTIVE"));mvc.perform(post("/api/v1/warehouses/"+WA+"/deactivate").with(token()).contentType("application/json").content("{\"version\":1}")).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("INACTIVE"));mvc.perform(post("/api/v1/warehouses/"+WA+"/archive").with(token()).contentType("application/json").content("{\"version\":2}")).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("ARCHIVED"));}
@Test void databaseEnforcesCodesScanAndForeignKeys(){assertThrows(DataIntegrityViolationException.class,()->warehouse(A,UUID.randomUUID(),"a-01"));assertDoesNotThrow(()->warehouse(B,UUID.randomUUID(),"A-01"));assertThrows(DataIntegrityViolationException.class,()->location(A,WA,ZA,UUID.randomUUID(),"OTHER","SCAN-A"));assertThrows(DataIntegrityViolationException.class,()->location(A,WB,ZB,UUID.randomUUID(),"BAD","BAD"));}
@Test void unauthenticatedDenied()throws Exception{mvc.perform(get("/api/v1/warehouses")).andExpect(status().isUnauthorized());}
@Test void warehouseFilteringPaginationAndSortValidation()throws Exception{mvc.perform(get("/api/v1/warehouses?q=A-01&status=DRAFT&page=0&size=1&sort=code,desc").with(token())).andExpect(status().isOk()).andExpect(jsonPath("$.totalElements").value(1));mvc.perform(get("/api/v1/warehouses/"+WA+"/zones?type=STORAGE&status=ACTIVE&sort=code,asc").with(token())).andExpect(status().isOk()).andExpect(jsonPath("$.totalElements").value(1));mvc.perform(get("/api/v1/warehouses?sort=tenantId,asc").with(token())).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("INVALID_SORT"));mvc.perform(get("/api/v1/warehouses?size=101").with(token())).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("INVALID_PAGINATION"));}
@Test void zoneUpdateIsVersionedAuditedAndArchiveProtectsChildren()throws Exception{mvc.perform(patch("/api/v1/warehouse-zones/"+ZA).with(token()).contentType("application/json").content("{\"code\":\"A2\",\"name\":\"Updated\",\"type\":\"PICKING\",\"sequence\":2,\"version\":0}")).andExpect(status().isOk()).andExpect(jsonPath("$.code").value("A2")).andExpect(jsonPath("$.type").value("PICKING"));assertEquals(1,db.queryForObject("SELECT count(*) FROM audit_events WHERE action='ZONE_UPDATED' AND entity_type='warehouse-zone'",Integer.class));mvc.perform(post("/api/v1/warehouse-zones/"+ZA+"/archive").with(token()).contentType("application/json").content("{\"version\":1}")).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("ZONE_HAS_ACTIVE_LOCATIONS"));mvc.perform(patch("/api/v1/warehouse-zones/"+ZA).with(token()).contentType("application/json").content("{\"code\":\"A2\",\"name\":\"Stale\",\"type\":\"PICKING\",\"sequence\":2,\"version\":0}")).andExpect(status().isConflict()).andExpect(jsonPath("$.code").value("CONCURRENT_MODIFICATION"));}
@Test void locationUpdateUsesExplicitFieldsAndFilters()throws Exception{mvc.perform(patch("/api/v1/warehouse-locations/"+LA).with(token()).contentType("application/json").content("{\"zoneId\":\""+ZA+"\",\"name\":\"Updated Bin\",\"type\":\"BIN\",\"sequence\":7,\"maxWeightGrams\":10,\"lengthMm\":20,\"widthMm\":30,\"heightMm\":40,\"version\":0,\"warehouseId\":\""+WB+"\",\"code\":\"HACK\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.code").value("A")).andExpect(jsonPath("$.warehouseId").value(WA.toString())).andExpect(jsonPath("$.heightMm").value(40));mvc.perform(get("/api/v1/warehouses/"+WA+"/locations?zoneId="+ZA+"&type=BIN&status=ACTIVE&code=A&q=updated&sort=sequence,desc").with(token())).andExpect(status().isOk()).andExpect(jsonPath("$.totalElements").value(1));mvc.perform(get("/api/v1/warehouses/"+WA+"/locations?sort=warehouseId").with(token())).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("INVALID_SORT"));}
@Test void multiLevelCycleAndArchiveParentAreRejected()throws Exception{UUID child=UUID.randomUUID(),grandchild=UUID.randomUUID();db.update("INSERT INTO warehouse_locations(id,tenant_id,warehouse_id,zone_id,parent_location_id,code,normalized_code,type,status,scan_code,normalized_scan_code,created_at,updated_at,version)VALUES (?,?,?,?,?,?,?,'BIN','ACTIVE',?,?,now(),now(),0)",child,A,WA,ZA,LA,"CHILD","CHILD","SCAN-CHILD","SCAN-CHILD");db.update("INSERT INTO warehouse_locations(id,tenant_id,warehouse_id,zone_id,parent_location_id,code,normalized_code,type,status,scan_code,normalized_scan_code,created_at,updated_at,version)VALUES (?,?,?,?,?,?,?,'BIN','ACTIVE',?,?,now(),now(),0)",grandchild,A,WA,ZA,child,"GRAND","GRAND","SCAN-GRAND","SCAN-GRAND");mvc.perform(post("/api/v1/warehouse-locations/"+LA+"/move").with(token()).contentType("application/json").content("{\"newParentId\":\""+grandchild+"\",\"version\":0}")).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("LOCATION_CYCLE"));mvc.perform(post("/api/v1/warehouse-locations/"+LA+"/archive").with(token()).contentType("application/json").content("{\"version\":0}")).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("LOCATION_HAS_ACTIVE_CHILDREN"));}
@Test void crossTenantMutationsAndTopologyAreHidden()throws Exception{mvc.perform(patch("/api/v1/warehouses/"+WB).with(token()).contentType("application/json").content("{\"code\":\"B-01\",\"name\":\"X\",\"timezone\":\"UTC\",\"version\":0}")).andExpect(status().isNotFound());mvc.perform(patch("/api/v1/warehouse-zones/"+ZB).with(token()).contentType("application/json").content("{\"code\":\"B\",\"name\":\"X\",\"type\":\"STORAGE\",\"sequence\":0,\"version\":0}")).andExpect(status().isNotFound());mvc.perform(post("/api/v1/warehouse-locations/"+LB+"/block").with(token()).contentType("application/json").content("{\"version\":0}")).andExpect(status().isNotFound());mvc.perform(get("/api/v1/warehouses/"+WB+"/topology").with(token())).andExpect(status().isNotFound());}
@Test void crossWarehouseMoveZoneAndDefaultAreRejected()throws Exception{UUID w2=UUID.randomUUID(),z2=UUID.randomUUID(),l2=UUID.randomUUID();warehouse(A,w2,"A-02");zone(A,w2,z2,"Z2");location(A,w2,z2,l2,"L2","SCAN-2");mvc.perform(post("/api/v1/warehouse-locations/"+LA+"/move").with(token()).contentType("application/json").content("{\"newParentId\":\""+l2+"\",\"version\":0}")).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("CROSS_WAREHOUSE_LOCATION_REFERENCE"));mvc.perform(patch("/api/v1/warehouse-locations/"+LA).with(token()).contentType("application/json").content("{\"zoneId\":\""+z2+"\",\"name\":\"X\",\"type\":\"BIN\",\"sequence\":0,\"version\":0}")).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("CROSS_WAREHOUSE_ZONE_REFERENCE"));mvc.perform(put("/api/v1/warehouses/"+WA+"/defaults/receiving").with(token()).contentType("application/json").content("{\"locationId\":\""+l2+"\"}")).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("CROSS_WAREHOUSE_LOCATION_REFERENCE"));}
@Test void readOnlyPermissionCannotMutate()throws Exception{db.update("DELETE FROM role_permissions WHERE tenant_id=? AND permission_key IN ('warehouse:update','warehouse-location:manage')",A);mvc.perform(patch("/api/v1/warehouses/"+WA).with(token()).contentType("application/json").content("{\"code\":\"A-01\",\"name\":\"X\",\"timezone\":\"UTC\",\"version\":0}")).andExpect(status().isForbidden());mvc.perform(post("/api/v1/warehouse-locations/"+LA+"/block").with(token()).contentType("application/json").content("{\"version\":0}")).andExpect(status().isForbidden());}
@Test void scanConflictHasStableCode()throws Exception{mvc.perform(post("/api/v1/warehouses/"+WA+"/locations").with(token()).contentType("application/json").content("{\"zoneId\":\""+ZA+"\",\"code\":\"UNIQUE\",\"type\":\"BIN\",\"sequence\":0,\"scanCode\":\"SCAN-A\"}")).andExpect(status().isConflict()).andExpect(jsonPath("$.code").value("LOCATION_SCAN_CODE_EXISTS"));}
@Test void openApiContainsEveryWarehouseOperation()throws Exception{mvc.perform(get("/v3/api-docs")).andExpect(status().isOk()).andExpect(jsonPath("$.paths['/api/v1/warehouse-zones/{id}'].patch").exists()).andExpect(jsonPath("$.paths['/api/v1/warehouse-zones/{id}/archive'].post").exists()).andExpect(jsonPath("$.paths['/api/v1/warehouse-locations/{id}'].patch").exists()).andExpect(jsonPath("$.paths['/api/v1/warehouse-locations/{id}/move'].post").exists()).andExpect(jsonPath("$.paths['/api/v1/warehouse-locations/lookup'].get").exists()).andExpect(jsonPath("$.paths['/api/v1/warehouses/{id}/topology'].get").exists()).andExpect(jsonPath("$.paths['/api/v1/warehouses/{id}/defaults/{purpose}'].put").exists());}
private org.springframework.test.web.servlet.request.RequestPostProcessor token(){return jwt().jwt(j->j.subject("user-a").claim("tenant_id",A.toString()));}private void org(UUID id,String slug){db.update("INSERT INTO organizations(id,name,slug,status,default_locale,default_timezone,default_currency,created_at,updated_at,version)VALUES (?,?,?,'ACTIVE','en','UTC','EUR',now(),now(),0)",id,slug,slug);}private void warehouse(UUID t,UUID id,String code){db.update("INSERT INTO warehouses(id,tenant_id,code,normalized_code,name,status,timezone,created_at,updated_at,version)VALUES (?,?,?,?,?,'DRAFT','UTC',now(),now(),0)",id,t,code,code.toUpperCase(),code);}private void zone(UUID t,UUID w,UUID id,String code){db.update("INSERT INTO warehouse_zones(id,tenant_id,warehouse_id,code,normalized_code,name,type,status,created_at,updated_at,version)VALUES (?,?,?,?,?,?,'STORAGE','ACTIVE',now(),now(),0)",id,t,w,code,code,code);}private void location(UUID t,UUID w,UUID z,UUID id,String code,String scan){db.update("INSERT INTO warehouse_locations(id,tenant_id,warehouse_id,zone_id,code,normalized_code,type,status,scan_code,normalized_scan_code,created_at,updated_at,version)VALUES (?,?,?,?,?,?, 'BIN','ACTIVE',?,?,now(),now(),0)",id,t,w,z,code,code,scan,scan);}}
